from scipy.signal import lsim
dt=0.001
def tf_out(num,den,u,t):
    # num=[n0,n1] for n0 + n1 s, den=[a0,a1] for s^2 + a1 s + a0 ; output via ss controllable
    a0,a1=den
    A=np.array([[0,1],[-a0,-a1]]); B=np.array([[0],[1]])
    C=np.array([[num[0],num[1]]]); Dm=np.array([[0.0]])
    # output = n0*x1 + n1*x2 with x2 = x1' (controllable canonical): correct for num deg<=1
    _,y,_=lsim((A,B,C,Dm),u,t,X0=None)
    return y
def model_Q(p,d):
    t=d.time_s.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; Q=d.reactive_power_pu.values
    V0=V[0]; Q0=Q[0]
    a0,a1,n0,n1,m0,m1,k=p
    y1=tf_out((n0,n1),(a0,a1),V-V0,t)
    y2=tf_out((m0,m1),(a0,a1),Vs-Vs[0],t)
    return Q0+y1+y2
def res(p,keys):
    return np.concatenate([model_Q(p,D[k])-D[k].reactive_power_pu.values for k in keys])
for keys in [['E'],['A'],['G']]:
    best=None
    for a0 in [4,400,40000]:
      for a1 in [2,20]:
        try:
          r=least_squares(res,[a0,a1,2,0.0,1,0,0],args=(keys,),max_nfev=60)
